-- SQL DDL for ClickHouse, generated by ormbridge.

CREATE TABLE auth_user (
  id Int32
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE blog_category (
  id Int32,
  created_at DateTime64(3) DEFAULT now64(3),
  updated_at DateTime64(3),
  name String,
  slug String,
  parent_id Nullable(Int32)
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE blog_post (
  id Int32,
  created_at DateTime64(3) DEFAULT now64(3),
  updated_at DateTime64(3),
  public_id UUID DEFAULT generateUUIDv4(),
  title String,
  body String,
  status Enum8('draft' = 1, 'published' = 2) DEFAULT 'draft',
  rating Nullable(Decimal(4, 2)),
  view_count Int32 DEFAULT 0,
  is_featured Bool DEFAULT false,
  published_at DateTime64(3) DEFAULT now64(3),
  metadata String DEFAULT '{}' COMMENT 'JSON document',
  author_id Int32,
  editor_id Nullable(Int32),
  category_id Int32,
  INDEX blog_post_author_id_title_idx (author_id, title) TYPE set(100) GRANULARITY 4,
  INDEX post_pub_status_idx (published_at, status) TYPE set(100) GRANULARITY 4,
  INDEX blog_post_title_idx title TYPE bloom_filter GRANULARITY 1
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE blog_tag (
  id Int32,
  label String
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);

CREATE TABLE blog_post_tags (
  post_id Int32,
  tag_id Int32
)
ENGINE = MergeTree()
ORDER BY (post_id, tag_id)
PRIMARY KEY (post_id, tag_id);

CREATE TABLE blog_profile (
  id Int32,
  bio Nullable(String),
  avatar Nullable(String),
  user_id Int32
)
ENGINE = MergeTree()
ORDER BY (id)
PRIMARY KEY (id);
